//! The one contract between core and every client: UI, media controls, remote control,
//! agents. See docs/api-v1-freeze.md for the public compatibility rules. Plain data, serde + JSON Schema
//! (`docs/contract.schema.json`, regenerated by `UPDATE_SCHEMA=1 cargo test -p mpmp-core`).
//!
//! What is frozen in v1 is the **JSON wire format** and the **guarantees below**, not the
//! Rust signatures (docs/api-v1-freeze.md).
//!
//! # Versions
//!
//! [`CONTRACT_VERSION`] (1) changes only on a breaking change. [`CONTRACT_MINOR`] counts
//! additive changes; [`Snapshot::contract_minor`] and [`Snapshot::features`] tell a client
//! what the core it talks to supports, before it sends a field or command that core may
//! not know. API 1.0 includes the full baseline; `features` describes actual available capabilities.
//!
//! # Compatibility rules
//!
//! - **Core → client is lenient.** Every enum has an `unknown` fallback (`#[serde(other)]`):
//!   a value a newer core adds decodes as `Unknown` at any nesting level (an unknown
//!   `PlayState` inside a `Snapshot` inside an `Event` still decodes the event). Clients
//!   ignore unknown object fields.
//! - **Client → core is strict.** Commands and queries (and every object inside them)
//!   reject unknown fields: `unsupported` / `unknown_field`, with `details.field` naming
//!   it. An unknown command is `unsupported` / `unknown_command`, an unknown query
//!   `unknown_query`, an unknown variant inside either (a filter kind, a field, a play
//!   context …) `unknown_variant`. Malformed JSON is `invalid` / `invalid_json`; a
//!   missing field or a wrong type `invalid` / `invalid_request`. Nothing is ever applied
//!   half-understood. The JSON adapters enforce this (`CoreHandle::execute_json` /
//!   `query_json` compare what was sent with what was understood); the Rust types
//!   themselves decode leniently, because request types also travel core → client (a
//!   `Command` inside `ConfirmationRequested`, a `TrackQuery` inside a `PlaylistSummary`).
//!   The schema marks only the outermost request objects closed (`Request`, each `Query`
//!   variant), so shared definitions have one shape in every root; core enforces the
//!   strictness at every depth.
//! - `unknown` variants are a decode-only fallback: never send one.
//! - Optional request fields (not in the schema's `required`) default as documented; a
//!   client may omit them.
//! - Tagged values use one field name everywhere: `"type"`. [`Value`] is adjacently tagged
//!   (`{"type":"int","value":5}`); every other data-carrying enum is internally tagged.
//!
//! # Numbers
//!
//! Every integer in the contract is within ±(2^53 − 1) (the schema says so with
//! `minimum` / `maximum` on 64-bit fields), so JavaScript clients read them exactly; a
//! request beyond it is `out_of_range` where core checks it (`Seek.position_ms`). Counts,
//! indices, `offset` and `limit` are `u32`; durations and byte sizes `u64`; Unix times are
//! `i64` milliseconds named `*_at_ms` (`recorded_at_ms`, `started_at_ms` …).
//! `Snapshot.now_ms` and `PositionInfo.at_ms` are core's monotonic clock (milliseconds since
//! core started), not Unix time.
//!
//! # Absent values
//!
//! - **Core → client**: clients treat a missing field and `null` alike. Core leaves out
//!   optional fields that do not apply in receipts, errors (`details`) and confirmation
//!   outcomes, and leaves out `TrackInfo.replay_gain`, `TrackInfo.tags` and
//!   `PlaylistSummary.query_error` when they are empty, and an agent origin's `session`
//!   when the adapter gave none; every other optional field is sent, as `null` when it has
//!   no value.
//! - **Client → core**: a field the schema does not list as `required` may be omitted and
//!   then takes its documented default (where `null` is allowed it means the same). A
//!   required field must be sent even when `null` is one of its values: `SetRating.rating`
//!   is required, and `"rating": null` clears the rating.
//!
//! # Errors
//!
//! `details.field` is a JSON path from the root of the request: `command.tracks[2]` in a
//! `Request`, `query.filter.all[0].field` in a `Query` (whose root is the query itself).
//!
#![doc = include_str!("guarantees.md")]

use std::collections::BTreeMap;

use schemars::JsonSchema;
use serde::{Deserialize, Deserializer, Serialize};

/// Breaking changes only.
pub const CONTRACT_VERSION: u32 = 1;

/// Additive API changes since the complete API 1.0 baseline.
/// Snapshot.features lists all negotiated capabilities (docs/api-v1-changes.md).
pub const CONTRACT_MINOR: u32 = 0;

/// Most rows of full tracks in one page (`Tracks`, `PlaylistItems`, `QueuePage`,
/// `History`, `Search`).
pub const MAX_TRACK_PAGE: u32 = 1000;

/// Most rows in other pages (`Albums`, `Artists`, `Facet`, `Playlists`, `Actions`).
pub const MAX_PAGE: u32 = 5000;

/// Most parts of one `and` / `or` filter.
pub const MAX_FILTER_PARTS: u32 = 500;

/// Most nodes in one filter.
pub const MAX_FILTER_NODES: u32 = 2000;

/// Deepest nesting of one filter.
pub const MAX_FILTER_DEPTH: u32 = 64;

/// Most tracks a play context expands to (a search can match the whole library); a
/// larger context is cut.
pub const MAX_CONTEXT_TRACKS: u32 = 100_000;

/// Most tracks one `EditTags` or `TagEditPreview` names (more: `out_of_range`).
pub const MAX_TAG_EDIT_TRACKS: u32 = 1000;

/// Maximum UTF-8 bytes in each public person name, truncated at a character boundary.
pub const MAX_ARTIST_NAME_BYTES: usize = mpmp_library::MAX_TAG_VALUE_BYTES;

pub const MAX_COVER_EDIT_TRACKS: u32 = 1000;

pub const MAX_COVER_IMAGE_BYTES: u32 = 1_048_576;

pub const MAX_COVER_IMAGE_PIXELS: u64 = 16_777_216;

pub const MAX_COVER_IMAGE_EDGE: u32 = 8192;

pub const MAX_COVER_UNDO_BYTES: u64 = 67_108_864;

/// Longest accepted sleep timer (24 hours).
pub const MAX_SLEEP_TIMER_MS: u64 = 86_400_000;

pub const MAX_OUTPUT_DEVICES: usize = 256;

pub const MAX_OUTPUT_FORMAT_RANGES: usize = 1024;

macro_rules! id {
    ($(#[$doc:meta])* $name:ident($inner:ty)) => {
        $(#[$doc])*
        #[derive(Debug,
         Clone,
         Copy,
         Default,
         PartialEq,
         Eq,
         Hash,
         PartialOrd,
         Ord,
         Serialize,
         Deserialize,
         JsonSchema)]
        #[serde(transparent)]
        pub struct $name(pub $inner);
    };
}

id!(
    /// One entry of the play queue; the same track queued twice has two entries. Never
    /// reused, also across restarts (guarantee 6).
    EntryId(u64)
);
id!(
    /// A track in the library (stable across rescans).
    TrackId(i64)
);
id!(
    /// A library root folder.
    RootId(i64)
);
id!(
    /// A playlist (manual or smart).
    PlaylistId(i64)
);
id!(
    /// One item of a manual playlist; the same track added twice has two items.
    PlaylistItemId(i64)
);
id!(
    /// The queue's revision: bumped by every queue change; queue edits may name the
    /// revision they expect (`expected_revision`). Only grows, also across restarts.
    QueueRevision(u64)
);
id!(
    /// A playlist's own revision: bumped by every edit of that playlist.
    PlaylistRevision(u64)
);
id!(
    /// A background job, unique within one run and seeded from the clock. Later runs
    /// usually do not repeat IDs, but clock rollback can collide. Never save a JobId
    /// across core runs; history is not persisted.
    JobId(u64)
);
id!(
    /// One recorded play in the history.
    PlayEventId(i64)
);
id!(
    /// One recorded change to user data in the action journal (guarantee 15); undo it with
    /// `UndoAction`.
    ActionId(i64)
);
id!(
    /// One permission grant (`GrantPermission`). Never reused, also across restarts (also
    /// not the id of a grant for a session, which ends with core).
    GrantId(i64)
);

/// The most grants `ErrorDetails.forbidden_by` lists (its description says 8).
pub const MAX_FORBIDDEN_BY: usize = 8;

/// Decodes a required field whose value may be `null`: serde treats a missing `Option`
/// field as `None`, except with `deserialize_with`.
fn nullable<'de, D: Deserializer<'de>, T: Deserialize<'de>>(
    deserializer: D,
) -> Result<Option<T>, D::Error> {
    Option::<T>::deserialize(deserializer)
}

/// The schema of a required field whose value may be `null`: `Option<T>`'s, but listed in
/// `required` (see [`nullable`]).
struct Nullable<T>(std::marker::PhantomData<T>);

impl<T: JsonSchema> JsonSchema for Nullable<T> {
    fn inline_schema() -> bool {
        true
    }

    fn schema_name() -> std::borrow::Cow<'static, str> {
        format!("Nullable_{}", T::schema_name()).into()
    }

    fn json_schema(generator: &mut schemars::SchemaGenerator) -> schemars::Schema {
        <Option<T>>::json_schema(generator)
    }
}

/// Largest integer a JavaScript number holds exactly (2^53 − 1); every integer in the
/// contract is within ±this.
pub const MAX_SAFE_INTEGER: u64 = (1 << 53) - 1;

